package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection.KeyVal;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen2Test {

    private FormElement formElement;

    @Before
    public void setUp() {
        Attributes attributes = new Attributes();
        Tag tag = new Tag("form");
        formElement = new FormElement(tag, "", attributes);
    }

    @Test
    public void testFormData_emptyForm() {
        assertEquals(0, formElement.formData().size());
    }

    @Test
    public void testFormData_textInput() {
        Element textInput = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "text")
                .put("name", "textInput").put("value", "textValue"));
        formElement.addElement(textInput);

        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertTrue(formData.contains(KeyVal.create("textInput", "textValue")));
    }

    @Test
    public void testFormData_unNamedElement() {
        Element unNamedElement = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "text")
                .put("value", "value"));
        formElement.addElement(unNamedElement);

        List<KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testFormData_checkBoxChecked() {
        Element checkBoxChecked = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "checkbox")
                .put("name", "checkBox").put("checked").put("value", "checkedValue"));
        formElement.addElement(checkBoxChecked);

        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertTrue(formData.contains(KeyVal.create("checkBox", "checkedValue")));
    }

    @Test
    public void testFormData_checkBoxUnchecked() {
        Element checkBoxUnchecked = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "checkbox")
                .put("name", "checkBox").put("value", "uncheckedValue"));
        formElement.addElement(checkBoxUnchecked);

        List<KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testFormData_radioChecked() {
        Element radioChecked = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "radio")
                .put("name", "radio").put("checked").put("value", "checkedValue"));
        formElement.addElement(radioChecked);

        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertTrue(formData.contains(KeyVal.create("radio", "checkedValue")));
    }

    @Test
    public void testFormData_radioUnchecked() {
        Element radioUnchecked = new Element(Tag.valueOf("input"), "", new Attributes().put("type", "radio")
                .put("name", "radio").put("value", "uncheckedValue"));
        formElement.addElement(radioUnchecked);

        List<KeyVal> formData = formElement.formData();
        assertEquals(0, formData.size());
    }

    @Test
    public void testFormData_selectWithSelectedOption() {
        Element select = new Element(Tag.valueOf("select"), "", new Attributes().put("name", "select"));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "opt1").put("selected")));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "opt2")));
        formElement.addElement(select);

        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertTrue(formData.contains(KeyVal.create("select", "opt1")));
    }

    @Test
    public void testFormData_selectWithNoSelectedOption() {
        Element select = new Element(Tag.valueOf("select"), "", new Attributes().put("name", "select"));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "opt1")));
        formElement.addElement(select);

        List<KeyVal> formData = formElement.formData();
        assertEquals(1, formData.size());
        assertTrue(formData.contains(KeyVal.create("select", "opt1")));
    }

    @Test
    public void testFormData_multipleSelectOptions() {
        Element select = new Element(Tag.valueOf("select"), "", new Attributes().put("name", "select").put("multiple"));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "opt1").put("selected")));
        select.appendChild(new Element(Tag.valueOf("option"), "", new Attributes().put("value", "opt2").put("selected")));
        formElement.addElement(select);

        List<KeyVal> formData = formElement.formData();
        assertEquals(2, formData.size());
        assertTrue(formData.contains(KeyVal.create("select", "opt1")));
        assertTrue(formData.contains(KeyVal.create("select", "opt2")));
    }
}
